all_owned_types.actual_type:
∀ {α : Type u} {β : Type v} {f : α → β} {s : Set.{v} β} {a : α},
  @Eq.{1} Prop (@Membership.mem.{u, u} α (Set.{u} α) (@Set.instMembership.{u} α) (@Set.preimage.{u, v} α β f s) a)
    (@Membership.mem.{v, v} β (Set.{v} β) (@Set.instMembership.{v} β) s (f a))

∀ {ι : Type u_1} {α : ι → Type u_2} {s : Set.{u_1} ι} {t : (i : ι) → Set.{u_2} (α i)} {f : (i : ι) → α i},
  @Eq.{1} Prop
    (@Membership.mem.{max u_1 u_2, max u_1 u_2} ((i : ι) → α i) (Set.{max u_1 u_2} ((i : ι) → α i))
      (@Set.instMembership.{max u_1 u_2} ((i : ι) → α i)) (@Set.pi.{u_1, u_2} ι α s t) f)
    (∀ (i : ι),
      @Membership.mem.{u_1, u_1} ι (Set.{u_1} ι) (@Set.instMembership.{u_1} ι) s i →
        @Membership.mem.{u_2, u_2} (α i) (Set.{u_2} (α i)) (@Set.instMembership.{u_2} (α i)) (t i) (f i))
